func TestCollect_Agents_WritesOplog(t *testing.T) {
	sb := testutil.NewSandbox(t)
	defer sb.Cleanup()

	createAgentSource(t, sb, nil)
	claudeAgents := createAgentTarget(t, sb, "claude")
	if err := os.WriteFile(filepath.Join(claudeAgents, "local-agent.md"), []byte("# Local"), 0644); err != nil {
		t.Fatalf("write: %v", err)
	}

	sb.WriteConfig(`source: ` + sb.SourcePath + `
targets:
  claude:
    skills:
      path: ` + sb.CreateTarget("claude") + `
    agents:
      path: ` + claudeAgents + `
`)

	collectResult := sb.RunCLI("collect", "agents", "claude", "--force")
	collectResult.AssertSuccess(t)

	logResult := sb.RunCLI("log", "--json", "--cmd", "collect", "--tail", "1")
	logResult.AssertSuccess(t)

	line := strings.TrimSpace(logResult.Stdout)
	if line == "" {
		t.Fatal("expected collect oplog entry")
	}

	var entry map[string]any
	if err := json.Unmarshal([]byte(line), &entry); err != nil {
		t.Fatalf("failed to parse log entry: %v\nstdout=%s", err, logResult.Stdout)
	}

	if entry["cmd"] != "collect" {
		t.Fatalf("expected cmd=collect, got %v", entry["cmd"])
	}
	if entry["status"] != "ok" {
		t.Fatalf("expected status=ok, got %v", entry["status"])
	}

	args, ok := entry["args"].(map[string]any)
	if !ok {
		t.Fatalf("expected args object, got %T", entry["args"])
	}
	if args["kind"] != "agents" {
		t.Fatalf("expected kind=agents, got %v", args["kind"])
	}
	if args["pulled"] != float64(1) {
		t.Fatalf("expected pulled=1, got %v", args["pulled"])
	}
}

package install

import (
	"fmt"
	"net/url"
	"os"
	"strconv"
	"strings"
)

// Platform represents a git hosting platform.
type Platform int

const (
	PlatformUnknown     Platform = iota
	PlatformGitHub               // github.com and GitHub Enterprise
	PlatformGitLab               // gitlab.com and self-hosted GitLab
	PlatformBitbucket            // bitbucket.org
	PlatformAzureDevOps          // dev.azure.com and visualstudio.com
)

// extractHost returns the hostname from a clone URL.
// Supports HTTPS (https://host/...) and SSH (git@host:...) formats.
func extractHost(cloneURL string) string {
	s := strings.TrimSpace(cloneURL)
	if s == "" {
		return ""
	}

	// SSH: git@host:owner/repo.git
	if strings.Contains(s, "@") && strings.Contains(s, ":") && !strings.Contains(s, "://") {
		at := strings.Index(s, "@")
		colon := strings.Index(s[at:], ":")
		if colon > 0 {
			return s[at+1 : at+colon]
		}
	}

	// HTTPS or file://
	u, err := url.Parse(s)
	if err != nil || u.Host == "" {
		return ""
	}
	return u.Hostname()
}

// detectPlatform identifies the git hosting platform from a clone URL.
func detectPlatform(cloneURL string) Platform {
	host := strings.ToLower(extractHost(cloneURL))
	if host == "" {
		return PlatformUnknown
	}
	if strings.Contains(host, "github") {
		return PlatformGitHub
	}
	if strings.Contains(host, "gitlab") {
		return PlatformGitLab
	}
	if strings.Contains(host, "bitbucket") {
		return PlatformBitbucket
	}
	if host == "dev.azure.com" || host == "ssh.dev.azure.com" || strings.HasSuffix(host, ".visualstudio.com") {
		return PlatformAzureDevOps
	}
	return PlatformUnknown
}

// resolveToken looks up a token from environment variables based on the
// detected platform. Platform-specific vars take priority over the generic
// SKILLSHARE_GIT_TOKEN. Returns empty strings if no token is available or
// the URL is not HTTPS.
func resolveToken(cloneURL string) (token, username string) {
	if !isHTTPS(cloneURL) {
		return "", ""
	}

	platform := detectPlatform(cloneURL)
	switch platform {
	case PlatformGitHub:
		if t := os.Getenv("GITHUB_TOKEN"); t != "" {
			return t, "x-access-token"
		}
		if t := os.Getenv("GH_TOKEN"); t != "" {
			return t, "x-access-token"
		}
	case PlatformGitLab:
		if t := os.Getenv("GITLAB_TOKEN"); t != "" {
			return t, "oauth2"
		}
	case PlatformBitbucket:
		if t := os.Getenv("BITBUCKET_TOKEN"); t != "" {
			if u := os.Getenv("BITBUCKET_USERNAME"); u != "" {
				return t, u
			}
			return t, "x-token-auth"
		}
	case PlatformAzureDevOps:
		if t := os.Getenv("AZURE_DEVOPS_TOKEN"); t != "" {
			return t, "x-access-token"
		}
	}

	// Generic fallback — use platform-appropriate username, or preserve
	// existing URL username (e.g. https://myuser@host/... → myuser:token@...).
	if t := os.Getenv("SKILLSHARE_GIT_TOKEN"); t != "" {
		if u := urlUsername(cloneURL); u != "" {
			return t, u
		}
		switch platform {
		case PlatformGitLab:
			return t, "oauth2"
		case PlatformBitbucket:
			return t, "x-token-auth"
		default:
			return t, "x-access-token"
		}
	}
	return "", ""
}

// authEnv returns environment variables that inject token authentication
// via GIT_CONFIG_COUNT/KEY/VALUE (Git 2.31+). This avoids the git -c
// key=value format which breaks when tokens contain '=' characters.
// If GIT_CONFIG_COUNT is already set in the environment, the new entry
// is appended at the next available index to avoid overriding existing
// git config entries (e.g. from CI pipelines).
// Returns nil for SSH/file URLs or when no token is available.
func authEnv(cloneURL string) []string {
	token, username := resolveToken(cloneURL)
	if token == "" {
		return nil
	}

	host := extractHost(cloneURL)
	if host == "" {
		return nil
	}

	base := existingConfigCount()
	authed := fmt.Sprintf("https://%s:%s@%s/", username, token, host)
	original := originalPrefix(cloneURL, host)
	return []string{
		fmt.Sprintf("GIT_CONFIG_COUNT=%d", base+1),
		fmt.Sprintf("GIT_CONFIG_KEY_%d=url.%s.insteadOf", base, authed),
		fmt.Sprintf("GIT_CONFIG_VALUE_%d=%s", base, original),
	}
}

// AuthEnvForURL returns git auth injection env for HTTPS clone/pull URLs.
// Returns nil when no token is available or URL is not HTTPS.
func AuthEnvForURL(cloneURL string) []string {
	return authEnv(cloneURL)
}

// ResolveTokenForURL returns token credentials resolved from env vars for the
// provided HTTPS URL. Returns empty strings when no token is available.
func ResolveTokenForURL(cloneURL string) (token, username string) {
	return resolveToken(cloneURL)
}

// DetectPlatformForURL identifies the git hosting platform for a URL.
func DetectPlatformForURL(cloneURL string) Platform {
	return detectPlatform(cloneURL)
}

// existingConfigCount returns the current GIT_CONFIG_COUNT from the
// environment, or 0 if unset/invalid.
func existingConfigCount() int {
	s := os.Getenv("GIT_CONFIG_COUNT")
	if s == "" {
		return 0
	}
	n, err := strconv.Atoi(s)
	if err != nil || n < 0 {
		return 0
	}
	return n
}

// originalPrefix returns the URL prefix that git's insteadOf should match.
// If the URL already contains a username (e.g. https://user@host/...),
// the prefix includes it so the rewrite rule matches the actual URL.
func originalPrefix(cloneURL, host string) string {
	u, err := url.Parse(strings.TrimSpace(cloneURL))
	if err == nil && u.User != nil && u.User.Username() != "" {
		return fmt.Sprintf("https://%s@%s/", u.User.Username(), host)
	}
	return fmt.Sprintf("https://%s/", host)
}

// sanitizeTokens replaces any known credential values found in text with
// [REDACTED]. This prevents tokens and associated usernames from leaking
// in error messages.
func sanitizeTokens(text string) string {
	vars := []string{
		"GITHUB_TOKEN", "GH_TOKEN", "GITLAB_TOKEN", "BITBUCKET_TOKEN",
		"AZURE_DEVOPS_TOKEN", "SKILLSHARE_GIT_TOKEN", "BITBUCKET_USERNAME",
	}
	for _, v := range vars {
		if t := os.Getenv(v); t != "" {
			text = strings.ReplaceAll(text, t, "[REDACTED]")
		}
	}
	return text
}

// urlUsername extracts the username from an HTTPS URL, if present.
// Returns "" for URLs without userinfo (e.g. https://github.com/...).
func urlUsername(cloneURL string) string {
	u, err := url.Parse(strings.TrimSpace(cloneURL))
	if err != nil || u.User == nil {
		return ""
	}
	return u.User.Username()
}

// isHTTPS returns true if the URL uses the HTTPS scheme.
func isHTTPS(cloneURL string) bool {
	return strings.HasPrefix(strings.ToLower(strings.TrimSpace(cloneURL)), "https://")
}

// IsAuthError returns true when git stderr indicates an authentication failure.
func IsAuthError(output string) bool {
	return strings.Contains(output, "Authentication failed") ||
		strings.Contains(output, "Access denied") ||
		strings.Contains(output, "could not read Username") ||
		strings.Contains(output, "terminal prompts disabled")
}

// IsSSLError returns true when git stderr indicates a TLS/SSL certificate failure.
func IsSSLError(output string) bool {
	lower := strings.ToLower(output)
	return strings.Contains(lower, "ssl certificate problem") ||
		strings.Contains(lower, "unable to get local issuer certificate") ||
		strings.Contains(lower, "self signed certificate") ||
		strings.Contains(lower, "certificate verify failed") ||
		strings.Contains(lower, "certificate verification failed")
}

package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"skillshare/internal/install"
	"skillshare/internal/oplog"
	"skillshare/internal/resource"
	"skillshare/internal/trash"
	"skillshare/internal/ui"
)

// cmdUninstallAgents removes agents from the source directory by moving them to agent trash.
func cmdUninstallAgents(agentsDir string, opts *uninstallOptions, cfgPath string, trashBase string, start time.Time) error {
	if _, err := os.Stat(agentsDir); err != nil {
		if os.IsNotExist(err) {
			return fmt.Errorf("agents source directory does not exist: %s", agentsDir)
		}
		return fmt.Errorf("cannot access agents source: %w", err)
	}

	// Discover all agents for resolution
	discovered, discErr := resource.AgentKind{}.Discover(agentsDir)
	if discErr != nil {
		return fmt.Errorf("failed to discover agents: %w", discErr)
	}

	// Resolve targets
	var targets []resource.DiscoveredResource
	if opts.all {
		targets = discovered
		if len(targets) == 0 {
			ui.Info("No agents found")
			return nil
		}
	} else {
		for _, input := range opts.skillNames {
			found := false
			for _, d := range discovered {
				if d.Name == input || d.FlatName == input || d.RelPath == input || strings.TrimSuffix(d.RelPath, ".md") == input {
					targets = append(targets, d)
					found = true
					break
				}
			}
			if !found {
				return fmt.Errorf("agent %q not found in %s", input, agentsDir)
			}
		}

		// Resolve --group targets
		if len(opts.groups) > 0 {
			groupFiltered, err := filterDiscoveredAgentsByGroups(discovered, opts.groups, agentsDir)
			if err != nil {
				return err
			}
			if len(groupFiltered) == 0 {
				return fmt.Errorf("no agents found in group(s): %s", strings.Join(opts.groups, ", "))
			}
			// Deduplicate against already-resolved name targets
			seen := make(map[string]bool, len(targets))
			for _, t := range targets {
				seen[t.RelPath] = true
			}
			for _, d := range groupFiltered {
				if !seen[d.RelPath] {
					targets = append(targets, d)
				}
			}
		}
	}

	if len(targets) == 0 {
		return fmt.Errorf("specify agent name(s), --group, or --all")
	}

	// Confirmation (unless --force or --json)
	if !opts.force && !opts.jsonOutput {
		ui.Warning("Uninstalling %d agent(s)", len(targets))
		const maxDisplay = 20
		display := targets
		if len(display) > maxDisplay {
			display = display[:maxDisplay]
		}
		for _, t := range display {
			fmt.Printf("  - %s\n", strings.TrimSuffix(t.RelPath, ".md"))
		}
		if len(targets) > maxDisplay {
			fmt.Printf("  ... and %d more\n", len(targets)-maxDisplay)
		}
		fmt.Println()
		fmt.Print("Continue? [y/N] ")
		var input string
		fmt.Scanln(&input)
		input = strings.TrimSpace(strings.ToLower(input))
		if input != "y" && input != "yes" {
			ui.Info("Cancelled")
			return nil
		}
	}

	store, _ := install.LoadMetadata(agentsDir)
	var removed []string
	var failed []string

	for _, t := range targets {
		agentFile := filepath.Join(agentsDir, t.RelPath)

		displayName := strings.TrimSuffix(t.RelPath, ".md")
		if opts.dryRun {
			ui.Info("[dry-run] Would remove agent: %s", displayName)
			removed = append(removed, displayName)
			continue
		}

		// Trash the agent file (+ legacy sidecar if it still exists)
		metaName := strings.TrimSuffix(filepath.Base(t.RelPath), ".md")
		legacySidecar := filepath.Join(filepath.Dir(agentFile), metaName+".skillshare-meta.json")
		_, err := trash.MoveAgentToTrash(agentFile, legacySidecar, displayName, trashBase)
		if err != nil {
			ui.Error("Failed to remove %s: %v", displayName, err)
			failed = append(failed, displayName)
			continue
		}

		// Remove from centralized metadata store
		if store != nil {
			store.Remove(displayName)
		}

		ui.Success("Removed agent: %s", displayName)
		removed = append(removed, displayName)
	}

	// Save store after all removals
	if store != nil && len(removed) > 0 {
		store.Save(agentsDir) //nolint:errcheck
	}

	// JSON output
	if opts.jsonOutput {
		output := struct {
			Removed  []string `json:"removed"`
			Failed   []string `json:"failed"`
			DryRun   bool     `json:"dry_run"`
			Duration string   `json:"duration"`
		}{
			Removed:  removed,
			Failed:   failed,
			DryRun:   opts.dryRun,
			Duration: formatDuration(start),
		}
		var jsonErr error
		if len(failed) > 0 {
			jsonErr = fmt.Errorf("%d agent(s) failed to uninstall", len(failed))
		}
		return writeJSONResult(&output, jsonErr)
	}

	// Summary
	if !opts.dryRun {
		fmt.Println()
		ui.Info("%d agent(s) removed, %d failed", len(removed), len(failed))
		if len(removed) > 0 {
			ui.Info("Run 'skillshare sync agents' to update targets")
		}
	}

	// Oplog
	logUninstallAgentOp(cfgPath, removed, len(removed), len(failed), opts.dryRun, start)

	if len(failed) > 0 {
		return fmt.Errorf("%d agent(s) failed to uninstall", len(failed))
	}
	return nil
}

func logUninstallAgentOp(cfgPath string, names []string, removed, failed int, dryRun bool, start time.Time) {
	status := "ok"
	if failed > 0 && removed > 0 {
		status = "partial"
	} else if failed > 0 {
		status = "error"
	}
	e := oplog.NewEntry("uninstall", status, time.Since(start))
	e.Args = map[string]any{
		"resource_kind": "agent",
		"names":         names,
		"removed":       removed,
		"failed":        failed,
		"dry_run":       dryRun,
	}
	oplog.WriteWithLimit(cfgPath, oplog.OpsFile, e, logMaxEntries()) //nolint:errcheck
}
